import pandas as pd

def leetflex_banned_accnts(log_info: pd.DataFrame) -> pd.DataFrame:
    merged = log_info.merge(log_info, on="account_id", suffixes=("_a", "_b"))
    diff_ip = merged[merged["ip_address_a"] != merged["ip_address_b"]]
    overlap = diff_ip[(diff_ip["login_a"] <= diff_ip["logout_b"]) & (diff_ip["logout_a"] >= diff_ip["login_b"])]
    return pd.DataFrame({"account_id": overlap["account_id"].drop_duplicates()})
